// Strict-serialization tests use the upstream Boolean ABI, with NO provider generation.
#[test]fn command_dispatch_is_persisted_before_documented_provider_call(){let mut c=setup();open(&mut c);let l=c.get_loan("k1".into()).unwrap();assert!(l.policy_busy&&!l.policy_call_complete);assert_eq!(l.policy_sequence,U64(1));let mut found=false;for receipt in get_created_receipts(){for action in receipt.actions{if let near_sdk::mock::MockAction::FunctionCallWeight{method_name,args,..}=action{if method_name==b"freeze_wallet"{found=true;let args:near_sdk::serde_json::Value=near_sdk::serde_json::from_slice(&args).unwrap();assert_eq!(args.as_object().unwrap().len(),1);assert!(args.get("wallet_pubkey").is_some());}}}}assert!(found);}
#[test]fn known_terminal_read_loss_can_reconcile_but_cannot_dispatch_again(){let mut c=setup();open(&mut c);let l=c.get_loan("k1".into()).unwrap();result(PromiseResult::Successful(vec![]),NOW);let _=c.on_policy_action("k1".into(),l.nonce,l.policy_sequence);assert!(c.get_loan("k1".into()).unwrap().policy_call_complete);result(PromiseResult::Failed,NOW);assert!(!c.on_loan_policy("k1".into(),l.nonce,l.policy_sequence));ctx("anyone.near",0,NOW);rejected(||{let _=c.retry_loan_policy("k1".into(),l.nonce);});let _=c.reconcile_loan_policy("k1".into(),l.nonce);result(policy(true),NOW);assert!(c.on_loan_policy("k1".into(),l.nonce,l.policy_sequence));assert_eq!(c.get_loan("k1".into()).unwrap().state,LoanState::Offered);}
#[test]fn known_failed_action_and_wrong_state_allows_new_sequence_only_after_read(){let mut c=setup();open(&mut c);let old=c.get_loan("k1".into()).unwrap();result(PromiseResult::Failed,NOW);let _=c.on_policy_action("k1".into(),old.nonce,old.policy_sequence);result(policy(false),NOW);assert!(c.on_loan_policy("k1".into(),old.nonce,old.policy_sequence));assert!(!c.get_loan("k1".into()).unwrap().policy_busy);ctx("anyone.near",0,NOW);let _=c.retry_loan_policy("k1".into(),old.nonce);let new=c.get_loan("k1".into()).unwrap();assert!(new.policy_sequence.0>old.policy_sequence.0);result(PromiseResult::Successful(vec![]),NOW);assert!(matches!(c.on_policy_action("k1".into(),old.nonce,old.policy_sequence),PromiseOrValue::Value(false)));result(policy(true),NOW);assert!(!c.on_loan_policy("k1".into(),old.nonce,old.policy_sequence));assert!(!c.on_loan_policy("k1".into(),new.nonce,new.policy_sequence));assert!(c.get_loan("k1".into()).unwrap().policy_busy);}
#[test]fn unknown_freeze_forbids_opposite_command_title_funding_and_new_loan(){let mut c=setup();open(&mut c);ctx("alice.near",1,NOW);rejected(||{let _=c.cancel_loan("k1".into(),U64(1));});rejected(||{c.nft_transfer(a("bob.near"),"k1".into(),None,None);});rejected(||{fund(&mut c);});rejected(||{open(&mut c);});assert_eq!(c.get_loan("k1".into()).unwrap().policy_sequence,U64(1));}
#[test]fn unknown_thaw_cannot_close_or_refreeze_even_if_snapshot_is_already_unfrozen(){let mut c=setup();active(&mut c);ctx("alice.near",terms().repayment.0,NOW);let _=c.repay_loan("k1".into(),U64(1));let l=c.get_loan("k1".into()).unwrap();assert_eq!(l.state,LoanState::UnlockPending);result(policy(false),NOW);assert!(!c.on_loan_policy("k1".into(),l.nonce,l.policy_sequence));ctx("anyone.near",0,NOW+10000*SECOND);rejected(||{let _=c.reconcile_loan_policy("k1".into(),l.nonce);});rejected(||{let _=c.retry_loan_policy("k1".into(),l.nonce);});assert_eq!(c.get_payout_credit(a("lender.near")),terms().repayment);assert!(c.get_loan("k1".into()).unwrap().policy_busy);}
#[test]fn duplicate_action_callback_does_not_create_another_snapshot_after_terminality(){let mut c=setup();open(&mut c);let l=c.get_loan("k1".into()).unwrap();result(PromiseResult::Successful(vec![]),NOW);let _=c.on_policy_action("k1".into(),l.nonce,l.policy_sequence);result(PromiseResult::Failed,NOW);assert!(matches!(c.on_policy_action("k1".into(),l.nonce,l.policy_sequence),PromiseOrValue::Value(false)));assert!(c.get_loan("k1".into()).unwrap().policy_call_complete);}
#[test]fn callback_loss_and_restart_preserve_exact_outstanding_command(){let mut c=setup();open(&mut c);let before=c.get_loan("k1".into()).unwrap();env::state_write(&c);let mut reloaded:Contract=env::state_read().unwrap();assert_eq!(reloaded.get_loan("k1".into()).unwrap(),before);ctx("anyone.near",0,NOW+10000*SECOND);rejected(||{let _=reloaded.retry_loan_policy("k1".into(),before.nonce);});assert_eq!(reloaded.get_loan("k1".into()).unwrap(),before);}
#[test]fn unknown_registration_cannot_be_completed_by_invented_receipt_metadata(){let mut c=setup();collateral().remove(&"k1".into());let nonce=registration(&mut c);let raw=near_sdk::serde_json::json!({"owner":"keys.near","encrypted_data":"sealed-policy","version":1,"locked":true,"frozen":false,"registration_nonce":nonce,"registration_deposit":(N/10-COLLATERAL_STORAGE_DEPOSIT).to_string(),"generation_supported":true});result(PromiseResult::Successful(raw.to_string().into_bytes()),NOW);assert!(!c.on_collateral_checked("k1".into(),nonce));assert!(!c.get_collateral_binding("k1".into()).unwrap().ready);assert_eq!(config_required().user_liabilities.0,N/10);assert_eq!(c.get_payout_credit(a("minter.near")).0,0);}
